SELECT strftime(o.OrderDate,'%Y-%m') AS Month,COUNT(DISTINCT o.OrderID) OrdersCreated,COUNT(DISTINCT CASE WHEN l.UnpickedUnits>0 THEN o.OrderID END) UnpickedOrders,COUNT(CASE WHEN l.UnpickedUnits>0 THEN l.OrderLineID END) UnpickedLines,SUM(l.UnpickedUnits)::BIGINT UnpickedUnits FROM analytics.orders o JOIN analytics.order_lines l ON l.OrderID=o.OrderID AND l.ScenarioID=o.ScenarioID WHERE o.ScenarioID='base' GROUP BY 1 ORDER BY 1